"""TypeScript core pack, part 3: Classes & Interfaces, Typed Arrays & Tuples, Enums & Literals.

Answers are worked out by hand in Python (an insertion sort, index arithmetic, the enum's own numbering).
"""

from __future__ import annotations

from ._model import Maker, isort, js_slice
from ._tscore_basics import K
from ._ts_model import TS

# -- 5. Classes & Interfaces ----------------------------------------------

CLASSES: list[Maker] = [
    TS("class P { constructor(private x: number, public y: number) {} sum() { return this.x + this.y; } }\nconsole.log(new P($a, $b).sum());",
       K(lambda a, b, **_: a + b), "Parameter properties become fields, so sum adds both."),
    TS("class P { constructor(private x: number, public y: number) {} }\nconsole.log(new P($a, $b));", K(lambda a, b, **_: f"P {{ x: {a}, y: {b} }}"),
       "Private is only a compile-time rule, so both fields are printed."),
    TS("class C { constructor(private _n: number) {} get double() { return this._n * 2; } }\nconsole.log(new C($a).double);", K(lambda a, **_: a * 2),
       "A getter is read like a property."),
    TS("class C {\n  private _n = 0;\n  get n() { return this._n; }\n  set n(v: number) { this._n = Math.max(0, v); }\n}\nconst c = new C();\nc.n = -$a;\nconsole.log(c.n);",
       "0", "The setter clamps the negative value to 0."),
    TS("class C {\n  private _n = 0;\n  get n() { return this._n; }\n  set n(v: number) { this._n = Math.max(0, v); }\n}\nconst c = new C();\nc.n = $a;\nconsole.log(c.n);",
       K(lambda a, **_: a), "A positive value passes the clamp."),
    TS("class C { static count = 0; constructor() { C.count++; } }\nfor (let i = 0; i < $a; i++) new C();\nconsole.log(C.count);", K(lambda a, **_: a),
       "The static counter is shared by every instance."),
    TS("class M { static twice(n: number) { return n * 2; } }\nconsole.log(M.twice($a));", K(lambda a, **_: a * 2), "A static method is called on the class."),
    TS('class A { greet() { return "hi"; } }\nclass B extends A { greet() { return super.greet() + " $w"; } }\nconsole.log(new B().greet());',
       K(lambda w, **_: f"hi {w}"), "super.greet runs the parent method first."),
    TS("class A { constructor(public x: number) {} }\nclass B extends A { constructor(x: number, public y: number) { super(x * 2); } }\nconsole.log(new B($a, $b));",
       K(lambda a, b, **_: f"B {{ x: {a * 2}, y: {b} }}"), "The parent sets x doubled, then the child sets y."),
    TS('class A { name() { return "a"; } }\nclass B extends A { name() { return "b"; } }\nconst xs: A[] = [new A(), new B()];\nconsole.log(xs.map(o => o.name()));',
       "[ 'a', 'b' ]", "Each object uses its own class's method."),
    TS("interface Shape { area(): number }\nclass Sq implements Shape { constructor(private s: number) {} area() { return this.s ** 2; } }\nconsole.log(new Sq($a).area());",
       K(lambda a, **_: a * a), "area squares the side."),
    TS('interface U { name: string; age?: number }\nconst u: U = { name: "$w" };\nconsole.log(u.age ?? $a, u);', K(lambda a, w, **_: f"{a} {{ name: '{w}' }}"),
       "The optional age is missing, so the fallback is used."),
    TS("const base = { a: $a, b: $b };\nconst o = { ...base, b: $c };\nconsole.log(o);", K(lambda a, c, **_: {"a": a, "b": c}), "The later b overrides."),
    TS("const base: { a: number; b?: number } = { a: $a, b: $b };\nconst o = { b: $c, ...base };\nconsole.log(o);", K(lambda a, b, **_: {"b": b, "a": a}),
       "The spread comes last, so base wins and b keeps its first position."),
    TS("console.log(Object.assign({}, { a: $a }, { a: $b, c: $c }));", K(lambda b, c, **_: {"a": b, "c": c}), "Later sources overwrite earlier ones."),
    TS("class Calc {\n  constructor(private v = 0) {}\n  add(n: number) { this.v += n; return this; }\n  mul(n: number) { this.v *= n; return this; }\n  get value() { return this.v; }\n}\nconsole.log(new Calc($a).add($b).mul($c).value);",
       K(lambda a, b, c, **_: (a + b) * c), "Each call returns this, so the steps chain in order."),
    TS('class P {\n  constructor(public n: number) {}\n  toString() { return "P" + this.n; }\n}\nconsole.log("" + new P($a));', K(lambda a, **_: f"P{a}"),
       "Joining with text calls toString."),
    TS("class A {}\nclass B extends A {}\nconsole.log(new B() instanceof A, new A() instanceof B);", "true false", "A child is a parent, not the other way round."),
    TS("abstract class S { abstract area(): number; show() { return \"a\" + this.area(); } }\nclass Sq extends S { constructor(private s: number) { super(); } area() { return this.s ** 2; } }\nconsole.log(new Sq($a).show());",
       K(lambda a, **_: f"a{a * a}"), "The inherited show calls the child's area."),
    TS("class A { protected n = $a; }\nclass B extends A { get() { return this.n + $b; } }\nconsole.log(new B().get());", K(lambda a, b, **_: a + b),
       "A protected field is readable in a subclass."),
    TS("class T {\n  static next = 1;\n  id = T.next++;\n}\nconst a = new T();\nconst b = new T();\nconsole.log(a.id, b.id, T.next);", "1 2 3", "Each new object takes the next id."),
    TS("class A {\n  x = $a;\n  constructor() { this.x += $b; }\n}\nconsole.log(new A().x);", K(lambda a, b, **_: a + b), "The field initialiser runs before the constructor body."),
    TS("const a = { n: { v: $a } };\nconst b = { ...a };\nb.n.v = $b;\nconsole.log(a.n.v);", K(lambda b, **_: b), "Spread is shallow, so both share the inner object."),
    TS("interface O { f?: () => number }\nconst o: O = {};\nconsole.log(o.f?.() ?? $a);", K(lambda a, **_: a), "The method is missing, so the fallback is used."),
    TS("const o = { n: $a, get dbl() { return this.n * 2; } };\no.n = $b;\nconsole.log(o.dbl);", K(lambda b, **_: b * 2), "The getter reads n each time."),
    TS("console.log(JSON.stringify(new (class P { constructor(public x: number, public y: number) {} })($a, $b)));",
       K(lambda a, b, **_: '{"x":%d,"y":%d}' % (a, b)), "JSON.stringify writes the fields."),
    TS('class A { name() { return "A"; } }\nclass B extends A { name() { return super.name() + "B"; } }\nclass C extends B { name() { return super.name() + "C"; } }\nconsole.log(new C().name());',
       "ABC", "Each super call runs the parent first."),
    TS("class C { constructor(public n = $a) {} }\nconsole.log(new C().n, new C($b).n);", K(lambda a, b, **_: f"{a} {b}"), "The default is used when no argument is given."),
    TS("class C {\n  private constructor(public n: number) {}\n  static make(n: number) { return new C(n * 2); }\n}\nconsole.log(C.make($a).n);", K(lambda a, **_: a * 2),
       "The factory builds the object with a doubled value."),
    TS("class P { constructor(public x: number, public y: number) {} }\nconsole.log(Object.keys(new P($a, $b)));", "[ 'x', 'y' ]", "The parameter properties are own fields."),
    TS("class L {\n  readonly xs: number[] = [];\n  add(n: number) { this.xs.push(n); }\n}\nconst l = new L();\nl.add($a); l.add($b);\nconsole.log(l.xs);", K(lambda a, b, **_: [a, b]),
       "readonly stops reassigning xs, not pushing into it."),
    TS("const p = { x: $a };\nconst q = { x: $a };\nconsole.log(p === q, p.x === q.x, JSON.stringify(p) === JSON.stringify(q));", "false true true",
       "Objects compare by identity, numbers by value."),
    TS("class C {\n  constructor(private _n: number) {}\n  get n() { return this._n; }\n}\nconsole.log(new C($a));", K(lambda a, **_: f"C {{ _n: {a} }}"),
       "Getters live on the prototype, so only the field is printed."),
    TS("interface A { n: number }\nconst x: A = { n: $a };\nconst y = x;\ny.n = $b;\nconsole.log(x.n);", K(lambda b, **_: b), "Both names point at the same object."),
    TS("class A {\n  static label = \"$w\";\n  static show() { return A.label.toUpperCase(); }\n}\nconsole.log(A.show());", K(lambda w, **_: w.upper()), "The static method reads the static field."),
    TS("class A { constructor(public n: number) {} equals(o: A) { return this.n === o.n; } }\nconsole.log(new A($a).equals(new A($a)), new A($a) === new A($a));",
       "true false", "The method compares values, the operator compares identity."),
]

# -- 6. Typed Arrays & Tuples ---------------------------------------------


def _strsort(xs):
    return isort([str(x) for x in xs])


ARRAYS: list[Maker] = [
    TS("console.log([$a, $b, $c].map(x => x * 2));", K(lambda a, b, c, **_: [a * 2, b * 2, c * 2]), "map doubles each item."),
    TS("console.log([$a, $b, $c, $d].filter(x => x % 2 === 0));", K(lambda a, b, c, d, **_: [x for x in (a, b, c, d) if x % 2 == 0]), "filter keeps the even numbers."),
    TS("console.log([$a, $b, $c].reduce((s, x) => s + x, $n));", K(lambda a, b, c, n, **_: n + a + b + c), "The sum starts from the initial value n."),
    TS('console.log(["$w", "$z"].reduce((s, x) => s + x.length, 0));', K(lambda w, z, **_: len(w) + len(z)), "reduce adds up the lengths."),
    TS("console.log([$m, $n, $a].sort());", K(lambda m, n, a, **_: [int(s) for s in _strsort((m, n, a))]),
       "The default sort compares as strings, so 10 comes before 9."),
    TS("console.log([$a, $b, $c].sort((x, y) => y - x));", K(lambda a, b, c, **_: isort([a, b, c])[::-1]), "The comparator sorts descending."),
    TS("console.log([$a, $m, $n].sort((x, y) => x - y));", K(lambda a, m, n, **_: isort([a, m, n])), "The comparator sorts by number, ascending."),
    TS("console.log([$a, $b, $c, $d].find(x => x > $h));", K(lambda a, b, c, d, h, **_: next((x for x in (a, b, c, d) if x > h), "undefined")),
       "find returns the first match, or undefined."),
    TS("console.log([$a, $b, $c, $d].findIndex(x => x > $h));", K(lambda a, b, c, d, h, **_: next((i for i, x in enumerate((a, b, c, d)) if x > h), -1)),
       "findIndex returns the position of the first match, or -1."),
    TS("console.log([$a, $b, $c].some(x => x > $m), [$a, $b, $c].every(x => x < $m));", "false true", "None is over m, and all are under m."),
    TS("console.log([$a, $b, $c].includes($d), [$a, $b, $c].indexOf($c));", "false 2", "d is not in the array, and c sits at index 2."),
    TS('console.log(["$w", "$z"].indexOf("$z"), ["$w", "$z"].indexOf("x"));', "1 -1", "A missing value gives -1."),
    TS("console.log([$a, $b, $c, $d].slice($k));", K(lambda a, b, c, d, k, **_: js_slice([a, b, c, d], k)), "slice(k) drops the first k items."),
    TS("console.log([$a, $b, $c, $d].slice(-2));", K(lambda c, d, **_: [c, d]), "A negative start counts from the end."),
    TS("console.log([$a, $b, $c, $d].slice(1, -1));", K(lambda b, c, **_: [b, c]), "slice(1, -1) drops the first and the last."),
    TS("const xs = [$a, $b, $c, $d];\nconst r = xs.splice(1, 2);\nconsole.log(xs, r);", K(lambda a, b, c, d, **_: f"[ {a}, {d} ] [ {b}, {c} ]"),
       "splice removes two items from index 1 and returns them."),
    TS("const xs = [$a, $b, $c];\nxs.splice(1, 0, $d);\nconsole.log(xs);", K(lambda a, b, c, d, **_: [a, d, b, c]), "splice with 0 deletions inserts."),
    TS("console.log([$a].concat([$b, $c], $d));", K(lambda a, b, c, d, **_: [a, b, c, d]), "concat flattens arrays one level and appends plain values."),
    TS('console.log([$a, $b, $c].join("-"));', K(lambda a, b, c, **_: f"{a}-{b}-{c}"), "join puts the separator between items."),
    TS("console.log([[$a, $b], [$c], []].flat());", K(lambda a, b, c, **_: [a, b, c]), "flat removes one level of nesting."),
    TS('console.log(["$w", "$z"].flatMap(s => [s.length, 0]));', K(lambda w, z, **_: [len(w), 0, len(z), 0]), "flatMap maps then flattens one level."),
    TS("const [x, y] = [$a, $b] as [number, number];\nconsole.log(y, x);", K(lambda a, b, **_: f"{b} {a}"), "Destructuring names the items in order."),
    TS("let p = $a, q = $b;\n[p, q] = [q, p];\nconsole.log(p, q);", K(lambda a, b, **_: f"{b} {a}"), "The destructuring assignment swaps them."),
    TS("const [first, ...rest] = [$a, $b, $c, $d];\nconsole.log(rest);", K(lambda b, c, d, **_: [b, c, d]), "The rest pattern collects the others."),
    TS("console.log(Object.entries({ x: $a, y: $b }));", K(lambda a, b, **_: [["x", a], ["y", b]]), "entries gives key and value pairs."),
    TS("console.log(Object.keys({ x: $a, y: $b }), Object.values({ x: $a, y: $b }));", K(lambda a, b, **_: f"[ 'x', 'y' ] [ {a}, {b} ]"), "keys and values come in the same order."),
    TS("const xs = [$a];\nxs[$k + 2] = $b;\nconsole.log(xs.length);", K(lambda k, **_: k + 3), "Writing past the end makes the length one more than the last index."),
    TS("const xs = [$a, $b, $c];\nconst ys = xs.reverse();\nconsole.log(xs === ys, xs);", K(lambda a, b, c, **_: f"true [ {c}, {b}, {a} ]"),
       "reverse changes the array itself and returns it."),
    TS("const xs = [$a, $b];\nconst ys = [...xs, $c];\nconsole.log(xs.length, ys.length);", "2 3", "The spread copy is a new, longer array."),
    TS('console.log(["$w", "$z"].map((s, i) => s[0] + i));', K(lambda w, z, **_: [w[0] + "0", z[0] + "1"]), "Each first letter gets its index."),
    TS('console.log(["$a", "$b"].map(Number));', K(lambda a, b, **_: [a, b]), "Number turns each text into a number."),
    TS('console.log(["1", "2", "3"].map(parseInt));', "[ 1, NaN, NaN ]", "map passes the index as parseInt's radix, which breaks 2 and 3."),
    TS("console.log(Array($k + 2).fill($b));", K(lambda k, b, **_: [b] * (k + 2)), "fill sets every slot."),
    TS("console.log([...Array($k + 2).keys()]);", K(lambda k, **_: list(range(k + 2))), "keys gives the indexes."),
    TS('console.log([..."$w"].slice($i));', K(lambda w, i, **_: list(w[i:])), "Spread splits into letters, slice drops the first i."),
    TS('console.log("$w".split("").reverse().join(""));', K(lambda w, **_: w[::-1]), "Split, reverse, join reverses a word."),
    TS('console.log(["$w", "$X", "$z"].sort());', K(lambda w, X, z, **_: isort([w, X, z])), "Capital letters sort before lowercase ones."),
    TS('console.log(["$w", "$z", "apple"].sort((p, q) => p.length - q.length));', K(lambda w, z, **_: sorted([w, z, "apple"], key=len)),
       "Sorted by length; equal lengths keep their order."),
    TS("console.log([$a, $b, $a, $c].lastIndexOf($a));", "2", "The last match is at index 2."),
    TS("console.log(Math.max(...[$a, $b, $c]));", K(lambda a, b, c, **_: max(a, b, c)), "Spread passes each item as an argument."),
    TS("const xs = [$a, $b];\nconsole.log(xs.push($c), xs.pop(), xs.shift());", K(lambda a, c, **_: f"3 {c} {a}"), "push returns the new length, pop the last item, shift the first."),
    TS("const xs = [$a, $b];\nconsole.log(xs.unshift($c), xs);", K(lambda a, b, c, **_: f"3 [ {c}, {a}, {b} ]"), "unshift adds at the front and returns the new length."),
    TS("console.log([$a, [$b, $c]].toString());", K(lambda a, b, c, **_: f"{a},{b},{c}"), "toString flattens into comma-separated items."),
    TS("let s = 0;\nfor (const [i, v] of [$a, $b].entries()) s += i * v;\nconsole.log(s);", K(lambda b, **_: b), "Index times value: 0 times a plus 1 times b."),
    TS("console.log([$a, $b, $c, $d].fill(0, 2));", K(lambda a, b, **_: [a, b, 0, 0]), "fill from index 2 overwrites the rest."),
    TS('const t: [string, number] = ["$w", $a];\nconst [s, n] = t;\nconsole.log(s.length + n);', K(lambda w, a, **_: len(w) + a), "The tuple is split into a string and a number."),
    TS("console.log([$a, $b, $c].map((x, i) => x * i));", K(lambda a, b, c, **_: [0, b, c * 2]), "Each item is multiplied by its index."),
    TS("console.log([$a, $b, $c].reduce((m, x) => (x > m ? x : m)));", K(lambda a, b, c, **_: max(a, b, c)), "Without an initial value the first item starts as the maximum."),
]

# -- 7. Enums & Literals --------------------------------------------------

ENUMS: list[Maker] = [
    TS("enum E { A = $a, B, C }\nconsole.log(E.C);", K(lambda a, **_: a + 2), "Members count up from the last set value."),
    TS("enum E { A = $a, B, C }\nconsole.log(E.B, E[$a]);", K(lambda a, **_: f"{a + 1} A"), "A numeric enum maps both ways, so E[a] is the name."),
    TS("enum E { A = $a, B, C }\nconsole.log(E[E.B], E[$a + 2]);", "B C", "The reverse mapping turns a number back into its name."),
    TS("enum E { A, B = $m, C }\nconsole.log(E.A, E.C);", K(lambda m, **_: f"0 {m + 1}"), "A starts at 0, C follows B."),
    TS("enum E { A = $a, B = A * 2, C }\nconsole.log(E.C);", K(lambda a, **_: a * 2 + 1), "B is a times 2, and C is one more."),
    TS('enum S { Up = "$w", Down = "$z" }\nconsole.log(S.Down + S.Up);', K(lambda w, z, **_: z + w), "String enum members hold their text."),
    TS("enum E { A = $a, B }\nconsole.log(Object.values(E));", K(lambda a, **_: ["A", "B", a, a + 1]), "A numeric enum has both the names and the numbers as values."),
    TS("enum E { A = $a, B }\nconsole.log(Object.keys(E));", K(lambda a, **_: [str(a), str(a + 1), "A", "B"]),
       "Number-like keys come first, in numeric order, then the names."),
    TS("enum E { A, B, C }\nenum S { A = \"a\", B = \"b\", C = \"c\" }\nconsole.log(Object.keys(E).length, Object.keys(S).length);", "6 3",
       "A numeric enum has an entry each way, a string enum only one."),
    TS('enum S { A = "x", B = "y" }\nconsole.log(Object.values(S));', "[ 'x', 'y' ]", "A string enum has only the forward direction."),
    TS('const D = { up: $a, down: $b } as const;\ntype K = keyof typeof D;\nconst k: K = "down";\nconsole.log(D[k]);', K(lambda b, **_: b), "keyof typeof lists the property names."),
    TS("const D = { up: $a, down: $b } as const;\nconsole.log(Object.keys(D), Object.values(D));", K(lambda a, b, **_: f"[ 'up', 'down' ] [ {a}, {b} ]"), "The object keeps its insertion order."),
    TS("const D = { up: $a, down: $b } as const;\nconsole.log(Object.entries(D));", K(lambda a, b, **_: [["up", a], ["down", b]]), "Each entry is a pair."),
    TS('type L = "$x" | "$y";\nconst v: L = "$y";\nconsole.log(v + v, v.length);', K(lambda y, **_: f"{y}{y} 1"), "A literal type is still a string."),
    TS("enum E { A, B, C }\nfunction f(e: E) { return e === E.B; }\nconsole.log(f(E.B), f(E.C));", "true false", "Enum members compare by their numbers."),
    TS("enum E { A, B, C }\nfunction f(e: E) { return e > E.A; }\nconsole.log(f(E.A), f(E.C));", "false true", "A numeric enum compares as numbers."),
    TS('enum E { A, B, C }\nconsole.log(E[$q]);', K(lambda q, **_: "ABC"[q]), "E[number] is the member's name."),
    TS('enum Color { Red, Green, Blue }\nfunction f(c: Color) { return Color[c]; }\nconsole.log(f(Color.Green), f(Color.Blue));', "Green Blue", "The reverse mapping gives the name."),
    TS("enum F { None = 0, R = 1, W = 2, X = 4 }\nconsole.log(F.R | F.X, (F.R | F.W) & F.W);", "5 2", "Flags combine with OR and test with AND."),
    TS("enum F { None = 0, R = 1, W = 2, X = 4 }\nconst p = F.R | F.W | F.X;\nconsole.log(p, (p & F.W) !== 0, (F.R & F.X) !== 0);", "7 true false", "p has every bit set, and R and X do not overlap."),
    TS('enum E { A, B }\nenum S { A = "a" }\nconsole.log(typeof E.A, typeof S.A);', "number string", "A numeric member is a number, a string member a string."),
    TS("enum E { A = $a, B }\ntype K = keyof typeof E;\nconst k: K = \"B\";\nconsole.log(E[k]);", K(lambda a, **_: a + 1), "keyof typeof E is the union of the names."),
    TS('const xs = ["$w", "$z"] as const;\ntype X = typeof xs[number];\nconst v: X = xs[1];\nconsole.log(v, xs.length);', K(lambda z, **_: f"{z} 2"),
       "typeof xs[number] is the union of the two words."),
    TS('function f(d: "up" | "down") { return d === "up" ? $a : -$a; }\nconsole.log(f("down"), f("up"));', K(lambda a, **_: f"-{a} {a}"), "The literal decides the sign."),
    TS("enum E { A = -$a, B, C }\nconsole.log(E.C);", K(lambda a, **_: 2 - a), "Counting up from a negative start."),
    TS("enum E { A = -$a, B }\nconsole.log(E[-$a]);", "A", "The reverse mapping works for negative numbers too."),
    TS("enum E { A = 1 << $k, B = 1 << ($k + 1) }\nconsole.log(E.A + E.B);", K(lambda k, **_: 2 ** k + 2 ** (k + 1)), "Each member is a shifted one."),
    TS("enum E { A = $a, B }\nconsole.log(E.B + \"\", E[$a] + \"!\");", K(lambda a, **_: f"{a + 1} A!"), "Adding text turns the number or the name into text."),
    TS("enum E { A, B }\nconsole.log(E.A === 0, E[0] === \"A\");", "true true", "Both directions are stored."),
    TS("type N = 1 | 2 | 3;\nconst xs: N[] = [3, 1, 2];\nconsole.log(xs.map(x => x * $a));", K(lambda a, **_: [3 * a, a, 2 * a]), "The literals are ordinary numbers at run time."),
    TS("enum E { A = $a, B, C }\nconsole.log(Object.values(E).filter(v => typeof v === \"number\"));", K(lambda a, **_: [a, a + 1, a + 2]), "The number values are the members' values."),
    TS("const E = { A: 0, B: 1 } as const;\ntype V = typeof E[keyof typeof E];\nconst v: V = 1;\nconsole.log(v);", "1", "V is the union 0 or 1."),
    TS('const m: Record<"a" | "b", number> = { a: $a, b: $b };\nconsole.log(m.a + m.b);', K(lambda a, b, **_: a + b), "The record has exactly the keys a and b."),
    TS("const enum E { A, B = $a }\nconsole.log(E.A, E.B);", K(lambda a, **_: f"0 {a}"), "A const enum is inlined as plain numbers."),
    TS('enum E { A = "a", B = "b" }\nfunction f(e: E) { return e === E.A ? $a : $b; }\nconsole.log(f(E.B));', K(lambda b, **_: b), "B is not A, so the else value is used."),
]
